	}
}"},{"rank":2,"score":43.5762,"file_path":"internal/ui/forge/explorer/create.go","start_line":108,"end_line":121,"focus_line":108,"snippet_start_line":108,"snippet_end_line":121,"symbol_start_line":108,"symbol_end_line":121,"language":"Go","kind":"method","symbol_id":"local/devdesk:Go:internal/ui/forge/explorer/create.go:method:Model.handleCreationSubmit","symbol_name":"handleCreationSubmit","qualified_name":"Model.handleCreationSubmit","signature":"func (m Model) handleCreationSubmit(msg components.CreationFormSubmitMsg) (tea.Model, tea.Cmd)","signals":["graph:calls","graph:incoming","graph:callers","complete-symbol"],"snippet":"func (m Model) handleCreationSubmit(msg components.CreationFormSubmitMsg) (tea.Model, tea.Cmd) {
