75		var b strings.Builder
76	
77		b.WriteString(theme.TitleStyle.Render("Loading templates..."))
78		b.WriteString("\n\n")
79	
80		spinnerStyle := lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorPrimary)
81		b.WriteString(spinnerStyle.Render(theme.IconHourglass + " Fetching templates from registry..."))
82		b.WriteString("\n\n")
83		b.WriteString(theme.HelpStyle.Render("Please wait..."))
84	
85		return lipgloss.NewStyle().
86			Background(theme.ColorBackground).
87			Border(lipgloss.NormalBorder()).
88			BorderForeground(theme.ColorPrimary).
89			BorderBackground(theme.ColorBackground).
90			Padding(1, 2).
91			Width(50).
92			Render(b.String())
93	}
