516	// GetHeaderInfo returns the key-value info for the header
517	func (m Model) GetHeaderInfo(context string) []shortcut.HeaderInfo {
518		info := []shortcut.HeaderInfo{
519			{Key: "Context", Value: context, Style: theme.HeaderValueStyle},
520		}
521		// The username, not the flag: a session whose user could not be read would
522		// otherwise put a bare "@" in the header.
523		if m.shared.CurrentUser.Username != "" {
524			info = append(info, shortcut.HeaderInfo{Key: "User", Value: "@" + m.shared.CurrentUser.Username, Style: theme.HeaderValueStyle})
525		}
526		if m.shared.IsAuthenticated && m.error == "" {
527			info = append(info, shortcut.HeaderInfo{
528				Key:   m.vocab().Namespaces,
529				Value: fmt.Sprintf("%d", len(m.nodes)),
530				Style: theme.HeaderValueStyle,
531			})
532		}
533		return info
534	}
