588						strings.ToLower(v.Namespace) + " or " + strings.ToLower(v.Repository) + ".",
589				},
590				{
591					Title: "CI Column Legend",
592					Body: "The CI column shows the status of the last pipeline for each project:\n" +
593						"  " + theme.IconOK + "  success — pipeline passed\n" +
594						"  " + theme.IconError + "  failed — pipeline failed\n" +
595						"  " + theme.IconRunning + "  running — pipeline in progress\n" +
596						"  " + theme.IconPending + "  pending — waiting to run\n" +
597						"  " + theme.IconManual + "  manual — awaiting manual trigger\n" +
598						"  " + theme.IconCanceled + "  canceled — pipeline was canceled\n" +
599						"  " + theme.IconSkipped + "  skipped — pipeline was skipped\n" +
600						"Groups show no CI status.",
601				},
602				{
603					Title: "Prerequisites",
604					Body: "You must be authenticated (via :" + string(command.ViewGitAuth) + ") to access the explorer. " +
605						"The clone method (SSH or HTTPS) is configurable in the context configuration.",
606				},
607			},
608		}
609	}
