package explorer

import (
	"fmt"
	"strings"
	"time"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/forge"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/help"
	"github.com/anthnel/devdesk/internal/ui/keymap"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
	"github.com/charmbracelet/lipgloss"
)

// View rend la vue
func (m Model) View() string {
	// Priority 1: Forms (full viewport replacement - Rule 112)
	if m.creationForm != nil {
		return m.creationForm.View()
	}

	// Priority 2: the clone list, which is a full viewport of its own — the
	// progress view and the report both (decision 9).
	if m.mode == ModeCloning && m.clone != nil {
		return m.clone.table.View()
	}

	// Priority 3: Modals (centered overlays)
	switch m.mode {
	case ModeLoadingTemplates:
		return lipgloss.Place(
			m.width, m.height,
			lipgloss.Center, lipgloss.Center,
			m.renderLoadingTemplates(),
			lipgloss.WithWhitespaceBackground(theme.ColorBackground),
		)
	case ModeConfirmingDelete:
		if m.deleteConfirmModal != nil {
			return lipgloss.Place(
				m.width, m.height,
				lipgloss.Center, lipgloss.Center,
				m.deleteConfirmModal.View(),
				lipgloss.WithWhitespaceBackground(theme.ColorBackground),
			)
		}
	}

	// Content style with left padding
	contentStyle := lipgloss.NewStyle().Background(theme.ColorBackground).PaddingLeft(1)

	// Normal view
	if !m.shared.IsAuthenticated {
		return contentStyle.Render(renderNotAuthenticated(m.vocab()))
	}

	if m.error != "" {
		return contentStyle.Render(renderError(m.error))
	}

	// The load says so in the footer, with a spinner, and the tree stays on
	// screen (Rule 139): whether it is loading, genuinely empty, or filtered
	// down to nothing, the body is the table alone — the row count is a header
	// field instead.
	return m.renderTable()
}

// loadingTree reports whether the group tree is still being fetched.
func (m Model) loadingTree() bool { return m.loading || !m.firstLoadDone }

// renderLoadingTemplates renders the template loading indicator
func (m Model) renderLoadingTemplates() string {
	var b strings.Builder

	b.WriteString(theme.TitleStyle.Render("Loading templates..."))
	b.WriteString("\n\n")

	spinnerStyle := lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorPrimary)
	b.WriteString(spinnerStyle.Render(theme.IconHourglass + " Fetching templates from registry..."))
	b.WriteString("\n\n")
	b.WriteString(theme.HelpStyle.Render("Please wait..."))

	return lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Border(lipgloss.NormalBorder()).
		BorderForeground(theme.ColorPrimary).
		BorderBackground(theme.ColorBackground).
		Padding(1, 2).
		Width(50).
		Render(b.String())
}

// renderTable renders the table content
func (m Model) renderTable() string {
	return m.table.View()
}

// GetFooterHeight returns the footer height for this view (Rule 124).
//
// The clone list has no breadcrumb — it is a flat list, and the tree's path
// says nothing about it — so it takes the two-line footer plus its own filter
// bar.
func (m Model) GetFooterHeight() int {
	if m.mode == ModeCloning && m.clone != nil {
		return 2 + m.clone.table.FilterBar().ExtraHeight()
	}
	if m.showsTree() {
		// filter bar (when visible) + breadcrumb tab bar + empty line + info line
		return 3 + m.table.FilterBar().ExtraHeight()
	}
	return 2 // empty line + info line
}

// RenderFooter returns the footer content rendered below the viewport (Rule 124).
func (m Model) RenderFooter(width int) string {
	infoLine := m.renderInfoLine(width)

	if m.mode == ModeCloning && m.clone != nil {
		var parts []string
		if bar := m.clone.table.FilterBar(); bar.IsVisible() {
			parts = append(parts, bar.View())
		}
		return strings.Join(append(parts, theme.EmptyLineBg(width), infoLine), "\n")
	}

	if m.showsTree() {
		var parts []string
		if bar := m.table.FilterBar(); bar.IsVisible() {
			parts = append(parts, bar.View())
		}
		parts = append(parts, m.renderTabBar(), theme.EmptyLineBg(width), infoLine)
		return strings.Join(parts, "\n")
	}
	return theme.EmptyLineBg(width) + "\n" + infoLine
}

// renderInfoLine is the footer's one line of text (Rule 128): a message when
// there is one, otherwise whatever the current mode has to say.
func (m Model) renderInfoLine(width int) string {
	return m.footer.View(width, m.status())
}

// status is what the view derives on every frame. None of the three has a
// timer: a clone run outlives the three seconds a message gets, and the load
// and the selection last exactly as long as they last.
func (m Model) status() components.Status {
	switch {
	case m.mode == ModeCloning && m.clone != nil:
		return components.Status{Text: m.cloneStatusLine()}
	case m.mode == ModeSelecting:
		return components.Status{Text: m.selectionStatusLine()}
	case m.shared.IsAuthenticated && m.loadingTree():
		return components.Status{Text: "Loading " + m.vocab().Name + " " + strings.ToLower(m.vocab().Namespaces) + "...", Spinner: true}
	}
	return components.Status{}
}

// selectionStatusLine states the selection in the only terms it can: the
// repository count is not known until discovery has run (decision 7), so what
// is shown is what was actually chosen.
func (m Model) selectionStatusLine() string {
	if m.selection.isEmpty() {
		return "Select groups and projects with space, then press enter"
	}
	roots, exclusions := m.selection.counts()
	line := plural(roots, "selection")
	if exclusions > 0 {
		line += " · " + plural(exclusions, "exclusion")
	}
	return line + " — enter to choose a destination"
}

// showsTree reports whether the tree table is what is on screen, which is what
// decides whether the footer carries a breadcrumb and a filter bar.
func (m Model) showsTree() bool {
	if !m.shared.IsAuthenticated || m.loading || m.error != "" || len(m.nodes) == 0 {
		return false
	}
	if m.creationForm != nil {
		return false
	}
	switch m.mode {
	case ModeNormal, ModeSelecting:
		return true
	default:
		return false
	}
}

// renderTabBar renders the tab bar at the bottom of the viewport
func (m Model) renderTabBar() string {
	tabs := []theme.TabItem{{Label: theme.IconHome + " home"}}
	for _, node := range m.navigationStack {
		if node != nil {
			tabs = append(tabs, theme.TabItem{Label: node.Name})
		}
	}
	if m.currentGroupNode != nil {
		tabs = append(tabs, theme.TabItem{Label: m.currentGroupNode.Name})
	}
	return theme.PadWithBg(theme.Bg(" ")+theme.RenderTabs(tabs, m.activeTabIndex), m.width)
}

// nodeTypeLabel returns the type label for a tree node, in the forge's own
// words: a GitLab user reads Group/Project, a GitHub user Organization/
// Repository.
func nodeTypeLabel(v forge.Vocabulary, node *TreeNode) string {
	if node.Type == NodeTypeGroup {
		return v.Namespace
	}
	return v.Repository
}

// vocab is the wording of the forge this context targets. Resolved from the
// config: the "not authenticated" screen needs the words before a session
// exists, so a value hanging off a live Forge would be unavailable exactly
// where it is needed most.
func (m Model) vocab() forge.Vocabulary {
	if m.config == nil {
		return forge.VocabularyFor("")
	}
	return forge.VocabularyFor(m.config.Forge.Type)
}

// forgeIcon is the glyph naming the active forge.
func (m Model) forgeIcon() string {
	if m.config == nil {
		return theme.ForgeIcon("")
	}
	return theme.ForgeIcon(m.config.Forge.Type)
}

// nodeKindIcon is the glyph the first column carries: a namespace or a
// repository.
//
// It says in one cell what the Type column used to say in thirteen, and it says
// it in no forge's words — which is the one thing lost and the one thing gained.
// Lost: a GitHub user no longer reads "Organization" on the row. Gained: the
// personal account's row no longer *claims* to be one (see docs/architecture/
// forge.md), and the vocabulary moved to the help legend, where nodeTypeLabel
// still resolves it and where a sentence has room to be right.
func nodeKindIcon(node *TreeNode) string {
	if node.Type == NodeTypeGroup {
		return theme.IconNamespace
	}
	return theme.IconRepository
}

// nodeKindRole is the same distinction as a colour, and it is what keeps the
// kind readable in the clone selection: there the glyph becomes a checkbox, so
// the hue is all that is left to say group or repository.
func nodeKindRole(node *TreeNode) theme.IconRole {
	if node.Type == NodeTypeGroup {
		return theme.IconRoleNamespace
	}
	return theme.IconRoleRepository
}

// visibilityIcon is GitLab's and GitHub's own alphabet: a globe for what anyone
// can read, a shield for what a signed-in user can, a lock for neither.
//
// An unknown visibility renders **nothing** rather than a placeholder glyph. The
// field is the backend's, and a forge that grows a fourth value would otherwise
// show one of the three existing ones — a wrong answer where an empty cell is a
// true one.
func visibilityIcon(node *TreeNode) string {
	switch node.Visibility {
	case "public":
		return theme.IconVisibilityPublic
	case "internal":
		return theme.IconVisibilityInternal
	case "private":
		return theme.IconLock
	}
	return ""
}

// visibilityRole colours the glyph above. An unknown visibility has no role, so
// IconStyle falls back to plain text — which is what an empty cell should be.
func visibilityRole(node *TreeNode) theme.IconRole {
	switch node.Visibility {
	case "public":
		return theme.IconRoleVisPublic
	case "internal":
		return theme.IconRoleVisInternal
	case "private":
		return theme.IconRoleVisPrivate
	}
	return ""
}

// visibilityLabel returns the visibility label for a tree node
func visibilityLabel(node *TreeNode) string {
	switch node.Visibility {
	case "public":
		return "Public"
	case "internal":
		return "Internal"
	case "private":
		return "Private"
	default:
		return ""
	}
}

// pipelineStatusLabel returns a status icon for the last CI pipeline.
//
// Every value forge.CIStatuses() declares has a case here, and
// TestEveryDeclaredCIStatusHasAnIcon walks that list to prove it. The default
// branch is therefore unreachable for a backend that keeps its promise — it
// stays because a backend that breaks it should still render *something*, and
// because that is how D66 was found: `created` and `scheduled` were missing
// from this switch, so a GitLab pipeline in either state printed its own name
// truncated to six cells.
//
// It switches on the constants rather than on literals so the two lists cannot
// drift again in silence: a renamed status stops compiling here.
func pipelineStatusLabel(node *TreeNode) string {
	if node.Type != NodeTypeProject || node.PipelineStatus == "" {
		return ""
	}
	switch node.PipelineStatus {
	case forge.CIStatusSuccess:
		return theme.IconOK
	case forge.CIStatusFailed:
		return theme.IconError
	case forge.CIStatusRunning:
		return theme.IconRunning
	// The five ways a pipeline can have not started yet. They share one glyph
	// because the difference between them is the scheduler's business, not the
	// reader's: all five answer "nothing has run".
	case forge.CIStatusPending, forge.CIStatusWaitingForResource, forge.CIStatusPreparing,
		forge.CIStatusCreated, forge.CIStatusScheduled:
		return theme.IconPending
	case forge.CIStatusCanceled:
		return theme.IconCanceled
	case forge.CIStatusSkipped:
		return theme.IconSkipped
	case forge.CIStatusManual:
		return theme.IconManual
	default:
		return node.PipelineStatus
	}
}

// pipelineStatusStyle colours the CI cell. A failed pipeline is the one thing
// in this table worth spotting without reading, and a green tick beside it is
// what makes it spottable — so success is coloured here where a running
// container is not: the CI column says nothing else, and most rows are not
// successes.
func pipelineStatusStyle(node *TreeNode) lipgloss.Style {
	if node.Type != NodeTypeProject {
		return theme.DimStyle
	}
	switch node.PipelineStatus {
	case "success":
		return theme.StatusOKStyle
	case "failed":
		return theme.StatusErrorStyle
	case "running":
		return lipgloss.NewStyle().Foreground(theme.ColorHighlight)
	case "canceled", "skipped", "manual", "":
		return theme.DimStyle
	default:
		return theme.StatusWarningStyle
	}
}

// Helper rendering functions

// renderNotAuthenticated names the forge and the command that signs into it.
//
// The command comes from internal/command rather than from a literal: it is
// routing identity, the same for both forges, and writing it out here is how a
// message survives a rename by going quietly wrong.
func renderNotAuthenticated(v forge.Vocabulary) string {
	style := lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorError)
	return style.Render(theme.IconWarning + " " + v.Name + " not authenticated\n\nPlease authenticate first with :" + string(command.ViewGitAuth))
}

func renderError(err string) string {
	style := lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorError)
	return style.Render(fmt.Sprintf("%s Error: %s", theme.IconError, err))
}

// timeAgo formats a time pointer as a compact relative string (Rule 127).
func timeAgo(t *time.Time) string {
	if t == nil {
		return ""
	}
	return theme.TimeAgo(*t)
}

// HeaderView interface implementation

func (m Model) GetShortcuts() shortcut.Shortcuts {
	// Mode-specific shortcuts
	switch m.mode {
	case ModeLoadingTemplates:
		return []shortcut.Shortcut{}
	case ModeSelecting:
		// ←→ keeps drilling here, and that is the point: deselecting inside a
		// ticked group means going into it (decision 10).
		return []shortcut.Shortcut{
			{Key: "space", Description: "Tick or untick"},
			{Key: "←→", Description: "Open/Back"},
			{Key: "enter", Description: "Choose a destination"},
			{Key: "/", Description: "Search"},
			{Key: "esc", Description: "Cancel"},
		}
	case ModeCloning:
		return m.cloningShortcuts()
	case ModeCreatingProject:
		return []shortcut.Shortcut{
			{Key: "↑↓", Description: "Navigate fields"},
			{Key: "←→", Description: "Select option"},
			{Key: "enter", Description: "Submit"},
			{Key: "esc", Description: "Cancel"},
		}
	case ModeConfirmingDelete:
		// ↑↓ is Rule 138 territory — obvious, so not advertised. It replaced
		// tab here when D4 was fixed.
		return []shortcut.Shortcut{
			{Key: "space", Description: "Toggle"},
			{Key: "y/n", Description: "Confirm"},
			{Key: "esc", Description: "Cancel"},
		}
	}

	// Signed out is a different screen — there is no tree, so there is nothing
	// to grey. That is a mode, not a state (Rule 130).
	if !m.shared.IsAuthenticated {
		return []shortcut.Shortcut{
			{Key: "ctrl+p", Description: "Command mode"},
		}
	}

	// Normal mode. A load in flight greys the lot rather than emptying it: the
	// tree is the same screen either side of a refresh, and a column that
	// vanishes and comes back on every ctrl+r is the flicker Rule 130 is about.
	loading := m.loading
	browse := m.browsable()

	return []shortcut.Shortcut{
		{Key: "←→", Description: "Open/Back", Disabled: loading},
		{Key: keymap.New, Description: "New", Disabled: loading},
		{Key: keymap.Delete, Description: "Delete", Disabled: loading},
		{Key: keymap.Clone, Description: "Clone", Disabled: loading},
		{Key: keymap.Web, Description: "Browser", Disabled: loading || !browse.Enabled()},
		{Key: ".", Description: "Sort", Disabled: loading},
		{Key: "/", Description: "Search", Disabled: loading},
		{Key: "ctrl+r", Description: "Refresh"},
		{Key: "ctrl+p", Description: "Command"},
		{Key: "?", Description: "Help"},
	}
}

// reasonNoWebURL is why W does not apply. The row exists, it simply has no page.
const reasonNoWebURL = "This entry has no web page to open"

// browsable reports whether W can open the selected row.
//
// Every node the forges return carries a WebURL, so in practice this only
// refuses on an empty level — but the handler already checked for it and
// returned in silence, which is what Rule 130 now forbids.
func (m Model) browsable() shortcut.Availability {
	if node, ok := m.selectedNode(); !ok || node.WebURL == "" {
		return shortcut.Unavailable(reasonNoWebURL)
	}
	return shortcut.Availability{}
}

// cloningShortcuts is state-aware (Rule 130): `esc` means three different
// things across a run, and offering the same word for all three is how a user
// presses it a second time expecting it to force.
func (m Model) cloningShortcuts() shortcut.Shortcuts {
	esc := shortcut.Shortcut{Key: "esc", Description: "Cancel"}
	switch {
	case m.clone == nil || m.clone.finished():
		esc.Description = "Close"
	case m.clone.cancelling:
		esc.Description = "Waiting for the running clones"
	}
	return []shortcut.Shortcut{
		esc,
		{Key: "/", Description: "Search"},
		{Key: ".", Description: "Sort"},
		{Key: "?", Description: "Help"},
	}
}

func (m Model) GetTitle() string {
	base := m.forgeIcon() + " " + m.vocab().Name + " Explorer"
	if m.creationForm != nil {
		return base + " " + theme.IconChevronRight + " " + m.creationForm.GetTitle()
	}
	switch m.mode {
	case ModeSelecting:
		return base + " " + theme.IconChevronRight + " Select what to clone"
	case ModeCloning:
		// The destination is in the title because it is the one thing the list
		// does not repeat on every row, and it is what a user checks first.
		if m.clone != nil {
			return base + " " + theme.IconChevronRight + " Cloning into " + m.clone.target
		}
	}
	return base
}

func (m Model) GetIcon() string {
	return ""
}

// GetHeaderInfo returns the key-value info for the header
func (m Model) GetHeaderInfo(context string) []shortcut.HeaderInfo {
	info := []shortcut.HeaderInfo{
		{Key: "Context", Value: context, Style: theme.HeaderValueStyle},
	}
	// The username, not the flag: a session whose user could not be read would
	// otherwise put a bare "@" in the header.
	if m.shared.CurrentUser.Username != "" {
		info = append(info, shortcut.HeaderInfo{Key: "User", Value: "@" + m.shared.CurrentUser.Username, Style: theme.HeaderValueStyle})
	}
	if m.shared.IsAuthenticated && m.error == "" {
		info = append(info, shortcut.HeaderInfo{
			Key:   m.vocab().Namespaces,
			Value: fmt.Sprintf("%d", len(m.nodes)),
			Style: theme.HeaderValueStyle,
		})
	}
	return info
}

// GetHelpContent retourne le contenu d'aide de la vue GitLab Explorer
func (m Model) GetHelpContent() help.Content {
	v := m.vocab()
	return help.Content{
		Title: v.Name + " Explorer",
		Description: "A drill-down explorer for browsing " + v.Name + " " + strings.ToLower(v.Namespaces) + " and " +
			strings.ToLower(v.Repositories) + ". Navigate into " + strings.ToLower(v.Namespaces) +
			" with → and go back with ←. Tabs at the bottom show your current path.",
		KeyBindings: []help.KeyBinding{
			{Key: "↑↓", Description: "Navigate the list"},
			{Key: "→", Description: "Drill into selected group"},
			{Key: "←", Description: "Go back to parent group"},
			{Key: "Esc", Description: "Go back to parent group"},
			{Key: keymap.Clone, Description: "Start a clone selection"},
			{Key: "Space", Description: "Tick or untick the selected row (selection mode)"},
			{Key: keymap.Web, Description: "Open the selected group or project in the default web browser"},
			{Key: keymap.New, Description: "Create a new group or project under the current context. Use ←→ to select the type."},
			{Key: keymap.Delete, Description: "Delete the selected group or project"},
			{Key: ".", Description: "Cycle sort column (Name → Created → Activity, then back to the forge's own order)"},
			{Key: "/", Description: "Filter the current level by name or path"},
			{Key: "Ctrl+R", Description: "Refresh the explorer"},
			{Key: "ctrl+p", Description: "Open command mode"},
			{Key: "?", Description: "Show this help"},
		},
		Sections: []help.Section{
			{
				Title: "Navigation",
				Body:  "The explorer uses a drill-down model. Press → on a group to see its contents. Press ← to go back. Tabs at the bottom show your current path.",
			},
			{
				Title: "Cloning",
				Body: "Press 'c' to enter selection mode. Every row gains a checkbox; press Space to tick a group or a project. " +
					"Ticking a group takes everything under it — drill in with → and untick what you do not want. " +
					"Press Enter to choose a destination directory in the workspace selector.\n" +
					"The clone list then fills as repositories are discovered, each row showing what it is doing. " +
					"A repository already on disk is skipped untouched; use the workspaces view to update one.\n" +
					"Press Esc to cancel: discovery stops immediately, but clones already running are allowed to finish " +
					"rather than being killed half-written. Press Esc again once it is done to return to the tree.",
			},
			{
				Title: "Creating Groups and Projects",
				Body:  "Press N to open the creation form. Use ←→ on the Type field to switch between Group and Project. The form uses the current group as parent. Project templates are loaded automatically from the OCI registry if configured.",
			},
			{
				Title: "Row Icons",
				Body: "The first column says what the row is, and the Visibility column who can read it:\n" +
					"  " + theme.IconNamespace + "  " + v.Namespace + "\n" +
					"  " + theme.IconRepository + "  " + v.Repository + "\n" +
					"  " + theme.IconVisibilityPublic + "  " + visibilityLabel(&TreeNode{Visibility: "public"}) + " — anyone can read it\n" +
					"  " + theme.IconVisibilityInternal + "  " + visibilityLabel(&TreeNode{Visibility: "internal"}) + " — any signed-in user can (" + v.Name + " only where the concept exists)\n" +
					"  " + theme.IconLock + "  " + visibilityLabel(&TreeNode{Visibility: "private"}) + " — members only\n" +
					"In clone selection mode the first column shows the checkbox instead; its colour still says " +
					strings.ToLower(v.Namespace) + " or " + strings.ToLower(v.Repository) + ".",
			},
			{
				Title: "CI Column Legend",
				Body: "The CI column shows the status of the last pipeline for each project:\n" +
					"  " + theme.IconOK + "  success — pipeline passed\n" +
					"  " + theme.IconError + "  failed — pipeline failed\n" +
					"  " + theme.IconRunning + "  running — pipeline in progress\n" +
					"  " + theme.IconPending + "  pending — waiting to run\n" +
					"  " + theme.IconManual + "  manual — awaiting manual trigger\n" +
					"  " + theme.IconCanceled + "  canceled — pipeline was canceled\n" +
					"  " + theme.IconSkipped + "  skipped — pipeline was skipped\n" +
					"Groups show no CI status.",
			},
			{
				Title: "Prerequisites",
				Body: "You must be authenticated (via :" + string(command.ViewGitAuth) + ") to access the explorer. " +
					"The clone method (SSH or HTTPS) is configurable in the context configuration.",
			},
		},
	}
}

package explorer

import (
	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/oci"
	"github.com/anthnel/devdesk/internal/shared"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// ViewMode represents the current mode of the view
type ViewMode int

const (
	ModeNormal ViewMode = iota
	// ModeSelecting is the clone selection: the same tree, with a checkbox on
	// every row and `Space` ticking it (§3.16, decision 8).
	ModeSelecting
	// ModeCloning is the discovery-and-clone pipeline: a flat list of what has
	// been found, each row carrying its own state. It replaced the modal that
	// said "Pulling..." for however many minutes the subtree took (decision 9).
	ModeCloning
	ModeLoadingTemplates
	ModeCreatingProject
	ModeConfirmingDelete
)

// Model représente le modèle de la vue GitLab Explorer
type Model struct {
	config *config.Config
	shared *shared.State
	width  int
	height int

	// Table
	table   datatable.Model[explorerRow]
	spinner spinner.Model

	// Tree state
	nodes         []*TreeNode
	loading       bool
	firstLoadDone bool // true after the first load attempt completes (success or error)
	error         string

	// Drill-down navigation
	currentGroupNode *TreeNode   // nil = root level
	navigationStack  []*TreeNode // Stack of parent groups for backspace navigation
	cursorStack      []int       // Cursor positions per level for restoration on drill-up

	mode ViewMode

	// Clone selection and the run it starts. The selection outlives every
	// drill-down — it names paths, not rows — and survives the round trip
	// through the workspaces view that picks the destination.
	selection cloneSelection
	// selectionNodes is where the walk starts from, one node per root. The
	// selection cannot hold them: it has to answer for paths nobody has fetched,
	// which is the whole reason it is paths and exclusions (decision 11). And a
	// root ticked three levels down is no longer on screen once the user has come
	// back up, so the reference has to be kept when it is made.
	selectionNodes map[string]*TreeNode
	clone          *cloneList

	// Creation mode state
	creationForm       *components.CreationForm
	creationParentName string              // Parent stashed during template loading
	creationParentID   string              // Parent ID stashed during template loading
	templateEntries    []oci.TemplateEntry // Loaded template entries for repo+tag resolution

	// Tab navigation
	activeTabIndex int // Focused tab index (last tab = current level)

	// Delete mode state
	deleteConfirmModal *components.OptionConfirmModal
	deleteTargetNode   *TreeNode
	// Transient footer messages, both cleared by the same 3s timer (Rule 128).
	// footer is the one line of transient state below the viewport (Rule 128).
	footer components.FooterMessage

	// Path to select after refresh (for newly created items)
	pendingSelectPath string
}

// New crée une nouvelle instance du modèle explorer
func New(cfg *config.Config, sharedState *shared.State) Model {
	s := spinner.New()
	s.Spinner = spinner.Dot
	s.Style = theme.SpinnerStyle()

	return Model{
		config:    cfg,
		shared:    sharedState,
		nodes:     []*TreeNode{},
		loading:   false,
		mode:      ModeNormal,
		selection: newCloneSelection(),
		table: datatable.New(datatable.Config[explorerRow]{
			Columns: explorerColumns(),
			// The forge's own order: loadChildren stacks the namespaces, then
			// the repositories. It used to be a sort by node type, which on
			// that list is the identity — so the opening screen is unchanged,
			// and what is gained is that `.` now has "no sort" as a stop, so
			// the forge's order is reachable again after cycling away from it.
			SortColumn: -1,
		}),
		spinner: s,
	}
}

// Init initialise le modèle
func (m Model) Init() tea.Cmd {
	// Charger les groupes racine au démarrage
	if m.shared.IsAuthenticated {
		m.loading = true
		return tea.Batch(m.spinner.Tick, m.loadRootGroups())
	}
	return nil
}

// InEditMode returns true if the view is in an edit mode or filter search.
//
// `m.mode != ModeNormal` already covers both clone modes, which is what it has
// to do: `c`, `space` and `esc` all mean something there, and a bare `:` would
// otherwise open command mode over a selection in progress.
func (m Model) InEditMode() bool {
	return m.creationForm != nil || m.mode != ModeNormal || m.table.InEditMode()
}

// FilterBarVisible returns true when the filter bar is visible (implements app.FilterBarView).
func (m Model) FilterBarVisible() bool {
	if m.mode == ModeCloning && m.clone != nil {
		return m.clone.table.FilterBar().IsVisible()
	}
	return m.showsTree() && m.table.FilterBar().IsVisible()
}

// tabCount returns the total number of tabs (home + navigation stack + current group)
func (m Model) tabCount() int {
	count := 1 // home tab
	for _, node := range m.navigationStack {
		if node != nil {
			count++
		}
	}
	if m.currentGroupNode != nil {
		count++
	}
	return count
}

// resize adjusts table dimensions based on terminal size
func (m *Model) resize(width, height int) {
	// Rule 124: the footer (tab bar + filter bar) is outside the viewport, so
	// only the table's own header row is subtracted. The Rule 116 arithmetic is
	// the component's — seven ratios and a remainder used to live here.
	m.table.Resize(width, max(height-1, 1))
	if m.clone != nil {
		m.clone.table.Resize(width, max(height-1, 1))
	}
}

package explorer

import (
	"strings"
	"time"
)

// NodeType représente le type de nœud dans l'arbre
type NodeType string

const (
	NodeTypeGroup   NodeType = "group"
	NodeTypeProject NodeType = "project"
)

// TreeNode représente un nœud dans l'arbre de la forge.
//
// Il survit à l'abstraction (§3.6) parce que ce qu'il porte en plus est de
// l'état de vue — développé, en cours de chargement, parent, profondeur — dont
// une forge n'a pas d'avis. Ce qu'il ne porte plus est ce que la forge décide :
// l'identifiant est opaque et le rôle est déjà un mot.
type TreeNode struct {
	// ID adresse le nœud auprès du backend et ne veut rien dire ici. C'était un
	// int64 — l'identifiant numérique de GitLab — que quatre sites convertissaient
	// en int pour le repasser au SDK.
	ID       string
	Name     string
	FullPath string
	Type     NodeType
	Children []*TreeNode
	Expanded bool
	Loading  bool // True when loading children
	Parent   *TreeNode
	Depth    int // Depth in tree (for rendering)

	// Metadata for flat table display
	Visibility string // "private", "internal", "public"
	// Role is already humanised — "Owner", "Maintainer", … — because the
	// backend humanises it: GitLab's numeric levels and GitHub's words do not
	// align one to one, so a view translating an integer would be translating
	// GitLab's. It replaces AccessLevel and AccessLevelName().
	Role              string
	CreatedAt         *time.Time // Creation date
	LastActivityAt    *time.Time // Last activity date
	PipelineStatus    string     // Last pipeline status ("success", "failed", "running", "pending", etc.)
	MarkedForDeletion bool       // True if the project is already scheduled for deletion
	WebURL            string     // Full HTTPS URL for opening in browser
}

// IsExpandable retourne vrai si le nœud peut être étendu
func (n *TreeNode) IsExpandable() bool {
	return n.Type == NodeTypeGroup
}

// Toggle expande ou contracte le nœud
func (n *TreeNode) Toggle() {
	if n.IsExpandable() {
		n.Expanded = !n.Expanded
	}
}

// nodeSlug returns the last path segment of a GitLab FullPath (the URL slug)
func nodeSlug(fullPath string) string {
	parts := strings.Split(fullPath, "/")
	return parts[len(parts)-1]
}

package explorer

import (
	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

// explorerRow is a node plus what the view knows about it and the node does not:
// whether it is ticked for cloning.
//
// The columns are built once in New and close over nothing, so a decoration that
// changes with a keystroke cannot be read from the model at render time — it has
// to travel on the row. That is the `imageRow` pattern, and it also means a
// column sorts by the same value it prints.
type explorerRow struct {
	node *TreeNode
	// selecting says whether the checkbox is shown at all. Outside the clone
	// selection mode the icon column prints the kind glyph alone, so a check
	// state left over from a previous selection cannot appear.
	selecting bool
	check     theme.CheckState
}

// checkboxIcon is RenderCheckboxTri's glyph without its styling.
//
// RenderCheckboxTri renders through lipgloss, and a styled string in a table
// cell is truncated mid-escape and bleeds over every row below it (Rule 122).
// The glyphs are the shared ones; only the styling is left behind.
func checkboxIcon(state theme.CheckState) string {
	switch state {
	case theme.CheckAll:
		return theme.IconChecked
	case theme.CheckSome:
		return theme.IconCheckboxIndeterminate
	default:
		return theme.IconCheckbox
	}
}

// iconCell is the first column: the checkbox while a clone selection is open,
// the kind glyph otherwise.
//
// One column for two things, because Rule 125 fixes an icon column at two
// cells and a checkbox beside a glyph needs four. What makes the sharing work
// is that the colour does not switch with the shape: iconStyle paints the kind
// in both modes, so a ticked row still says group or repository — by hue rather
// than by glyph, which is the whole reason the theme grew icon roles.
func iconCell(r explorerRow) string {
	if r.selecting {
		return checkboxIcon(r.check)
	}
	return nodeKindIcon(r.node)
}

// iconStyle colours the cell above by the node's kind, in both modes.
//
// Under the cursor it has no effect: datatable hands the selected row whole to
// styles.Selected, and a colour inside it would close with a reset that takes
// the selection background with it (Rule 122). That is the behaviour of every
// coloured column in the application, not an exception here.
func iconStyle(r explorerRow) lipgloss.Style {
	return theme.IconStyle(nodeKindRole(r.node))
}

// selectedNode returns the node under the cursor, which is what every action
// wants — none of them has anything to say about the decoration.
func (m Model) selectedNode() (*TreeNode, bool) {
	row, ok := m.table.Selected()
	if !ok {
		return nil, false
	}
	return row.node, true
}

// rowsFor wraps a level's nodes, stamping the current check state onto each.
//
// The state is read here rather than in the cell so that the table holds a
// settled value: `Space` rebuilds the rows, which is the one place the selection
// and what is on screen are brought back into agreement.
func (m Model) rowsFor(nodes []*TreeNode) []explorerRow {
	selecting := m.mode == ModeSelecting
	rows := make([]explorerRow, len(nodes))
	for i, node := range nodes {
		rows[i] = explorerRow{node: node, selecting: selecting}
		if selecting {
			rows[i].check = m.selection.state(node.FullPath)
		}
	}
	return rows
}

package explorer

import (
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// The clone list is the item level of a clone run (D3).
//
// It used to keep its own five states, its own rows, its own index and its own
// spinner frame — a fifth bookkeeping beside the four internal/jobs replaced,
// and the one the plan named as the prototype to generalise. Those five states
// are where jobs.ItemState came from, so the mapping is direct:
//
//	queued        → ItemQueued
//	cloning       → ItemRunning
//	cloned        → ItemDone
//	already there → ItemSkipped
//	failed        → ItemFailed
//
// What this screen is now is a **rendering** of the run: the rows are the
// snapshot's items, in the order the walk found them, and the frame is the
// router's (D5). Nothing here is authoritative, which is what lets `:jobs` show
// the same run without either copy drifting from the other.

// cloneRow is one target of the run, with the shared frame stamped on.
//
// The frame rides on the row because the columns are built once and close over
// nothing — the same reason jobsview has runRow. It is text rather than a
// rendered spinner because a table cell must carry no escape sequence
// (Rule 122).
type cloneRow struct {
	item  jobs.Item
	frame string
}

// cloneList is the ModeCloning screen: the run in flight and the table showing
// it. It is the progress view and the report both — decision 9 leaves modals
// for yes/no confirmations only.
type cloneList struct {
	table datatable.Model[cloneRow]

	// run is the last snapshot of this screen's run. It is a copy, replaced
	// whole on every broadcast — there is nothing to reconcile, which is what
	// removed the index and the upsert.
	run    jobs.Run
	target string

	// events is the pipeline's channel, and the only thing this struct still
	// owns. It is not state: it is what waitForCloneEvent blocks on.
	events <-chan cloneEvent

	// cancelling is set by `esc` and cleared by nothing: a run that is stopping
	// cannot be restarted, only awaited. A second `esc` must not force, because
	// forcing is the half-cloned directory decision 12 avoids.
	//
	// It is kept here rather than read back from the run for one frame's worth
	// of honesty: `esc` asks the router, and the answer arrives in the next
	// broadcast. Without it the key would look ignored until then.
	cancelling bool
}

const (
	colCloneStatusMin = 16
	colClonePathMin   = 30
	colCloneDetailMin = 20
)

// The column order, named so a test asserting on a cell does not hard-code the
// position it happens to sit at today.
const (
	colCloneRepository = iota
	colCloneDetail
	colCloneStatus
)

func newCloneList(target string, events <-chan cloneEvent) *cloneList {
	return &cloneList{
		target: target,
		events: events,
		table: datatable.New(datatable.Config[cloneRow]{
			Columns: cloneColumns(),
			// Discovery order, deliberately: it is the order things happened, and
			// a list that reorders itself while it fills is unreadable. `.` still
			// sorts on demand.
			SortColumn: -1,
		}),
	}
}

// cloneColumns describes the clone list.
//
// The repository comes first and the status last. The rows are one long list of
// paths under a common prefix, so the name is what the eye runs down to find a
// line; a status column on the left pushes every one of them right by sixteen
// cells and puts the changing text where the stable text should be.
func cloneColumns() []datatable.Column[cloneRow] {
	return []datatable.Column[cloneRow]{
		{
			Title: "Repository", Sizing: datatable.SizingContent, MinWidth: colClonePathMin, Flex: 2, TruncateHead: true,
			Cell:   func(r cloneRow) string { return r.item.Name() },
			Less:   func(a, b cloneRow) bool { return strings.ToLower(a.item.Name()) < strings.ToLower(b.item.Name()) },
			Search: func(r cloneRow) string { return r.item.Name() },
		},
		{
			Title: "Detail", Sizing: datatable.SizingContent, Optional: true, MinWidth: colCloneDetailMin, Flex: 1,
			Cell:   func(r cloneRow) string { return r.item.Detail },
			Search: func(r cloneRow) string { return r.item.Detail },
		},
		{
			Title: "Status", Sizing: datatable.SizingFixed, MinWidth: colCloneStatusMin,
			Cell:  cloneStatusLabel,
			Style: cloneStatusStyle,
			Less:  func(a, b cloneRow) bool { return a.item.State < b.item.State },
		},
	}
}

// cloneStatusLabel is the status cell: an icon and a word, plain text.
//
// The words are the clone's, not the registry's: "already there" is what a skip
// means here, where a sync's skip means something else entirely. The state is
// shared, the wording is the view's — the same split Reporter draws.
func cloneStatusLabel(r cloneRow) string {
	switch r.item.State {
	case jobs.ItemRunning:
		return r.frame + " cloning"
	case jobs.ItemDone:
		return theme.IconOK + " cloned"
	case jobs.ItemSkipped:
		return theme.IconSkipped + " already there"
	case jobs.ItemFailed:
		return theme.IconError + " failed"
	default:
		return theme.IconPending + " queued"
	}
}

// cloneStatusStyle colours the status cell.
//
// The five states are the whole vocabulary of this screen, and they are the one
// thing a run of forty rows is read for: which ones failed, which are still
// going, which were already on disk and were left alone.
func cloneStatusStyle(r cloneRow) lipgloss.Style {
	switch r.item.State {
	case jobs.ItemDone:
		return theme.StatusOKStyle
	case jobs.ItemFailed:
		return theme.StatusErrorStyle
	case jobs.ItemRunning:
		return lipgloss.NewStyle().Foreground(theme.ColorHighlight)
	default: // queued, and already there — neither is news
		return theme.DimStyle
	}
}

// setRun replaces the screen's copy of the run and rebuilds the table.
//
// The frame is stamped on the running rows here rather than held on each item,
// because it belongs to the list and not to any repository: one spinner, on
// every row that is going.
func (l *cloneList) setRun(run jobs.Run, frame string) {
	l.run = run
	items := make([]cloneRow, len(run.Items))
	for i, item := range run.Items {
		row := cloneRow{item: item}
		if item.State == jobs.ItemRunning {
			row.frame = frame
		}
		items[i] = row
	}
	l.table.SetItems(items)
}

// finished reports whether the run has settled: the walk sealed, and every
// target done with.
func (l *cloneList) finished() bool { return l.run.Finished() }

// running counts the clones still in flight, which is what `esc` has to wait
// for and what the view states while it does.
func (l *cloneList) running() int {
	n := 0
	for _, item := range l.run.Items {
		if item.State == jobs.ItemRunning {
			n++
		}
	}
	return n
}

// counts is the header line: what has been found and how it went.
func (l *cloneList) counts() (found, cloned, present, failed int) {
	c := l.run.Counts()
	return l.run.Total(), c[jobs.ItemDone], c[jobs.ItemSkipped], c[jobs.ItemFailed]
}

// failures returns the failed paths, for the log and the footer. Decision 13
// discards the list on `esc`, and workspaces records only the successes — a
// failure that wrote nothing leaves nothing behind, so it has to be said while
// the view is still alive.
func (l *cloneList) failures() []string {
	var out []string
	for _, item := range l.run.Items {
		if item.State == jobs.ItemFailed {
			out = append(out, item.Target)
		}
	}
	return out
}

// cloneRunFrom picks this screen's run out of the snapshot.
//
// The newest clone run, because there is exactly one at a time: ModeCloning
// owns the display while it goes, so a second could only start after this one
// has been closed. It is the invariant Registry.openRun rests on, read from the
// other side.
//
// A settled run still matches, which is what the report needs: the screen stays
// up after the walk has sealed, and `esc` is what finally drops it.
func cloneRunFrom(runs []jobs.Run) (jobs.Run, bool) {
	for i := len(runs) - 1; i >= 0; i-- {
		if runs[i].Kind == jobs.KindClone {
			return runs[i], true
		}
	}
	return jobs.Run{}, false
}

