package explorer

import (
	"strings"

	tea "github.com/charmbracelet/bubbletea"
)

// handleDrillDown handles enter key - navigate into a group
func (m Model) handleDrillDown() (tea.Model, tea.Cmd) {
	node, ok := m.selectedNode()
	if !ok || node.Type != NodeTypeGroup {
		return m, nil
	}

	// Save cursor position before navigating down
	m.cursorStack = append(m.cursorStack, m.table.Cursor())
	// Push current group onto navigation stack
	m.navigationStack = append(m.navigationStack, m.currentGroupNode)
	m.currentGroupNode = node
	m.activeTabIndex = m.tabCount() - 1

	// Load children if not yet loaded
	if node.Children == nil {
		node.Loading = true
		m.loading = true
		m.updateTableRows()
		return m, tea.Batch(m.spinner.Tick, m.loadChildren(node))
	}
	m.updateTableRows()
	m.table.GotoTop()
	return m, nil
}

// handleDrillUp handles backspace key - navigate back to parent
func (m Model) handleDrillUp() (tea.Model, tea.Cmd) {
	if len(m.navigationStack) == 0 {
		return m, nil
	}
	// Pop from stack
	m.currentGroupNode = m.navigationStack[len(m.navigationStack)-1]
	m.navigationStack = m.navigationStack[:len(m.navigationStack)-1]
	m.activeTabIndex = m.tabCount() - 1
	m.updateTableRows()
	// Restore cursor position at the parent level
	if len(m.cursorStack) > 0 {
		cursor := m.cursorStack[len(m.cursorStack)-1]
		m.cursorStack = m.cursorStack[:len(m.cursorStack)-1]
		m.table.SetCursor(cursor)
	} else {
		m.table.GotoTop()
	}
	return m, nil
}

// updateTableRows refills the table with the current drill-down level.
//
// The sort, the filter, the sort arrows and the cursor clamp were all written
// out in table.go; they are the component's now. What is left is the one thing
// this view knows and it does not: which level the table is showing.
func (m *Model) updateTableRows() {
	m.table.SetItems(m.rowsFor(m.currentItems()))
	// A drill-down is a different population, and a checkbox toggle widens the
	// Type cell by two — both are user actions on a settled list, which is what
	// Remeasure is for. datatable cannot tell either from a periodic reload:
	// they all arrive through SetItems.
	m.table.Remeasure()
}

// currentItems returns the children of the current drill-down group (or root nodes)
func (m Model) currentItems() []*TreeNode {
	if m.currentGroupNode == nil {
		return m.nodes
	}
	if m.currentGroupNode.Children == nil {
		return nil
	}
	return m.currentGroupNode.Children
}

// handleRefresh handles r key
func (m Model) handleRefresh() (tea.Model, tea.Cmd) {
	m.loading = true
	m.nodes = []*TreeNode{}
	m.currentGroupNode = nil
	m.navigationStack = nil
	m.cursorStack = nil
	m.activeTabIndex = 0
	m.table.SetItems(nil)
	return m, tea.Batch(m.spinner.Tick, m.loadRootGroups())
}

// handleChildrenLoaded handles ChildrenLoadedMsg
func (m Model) handleChildrenLoaded(msg ChildrenLoadedMsg) (tea.Model, tea.Cmd) {
	msg.ParentNode.Children = msg.Children
	msg.ParentNode.Expanded = true
	msg.ParentNode.Loading = false
	m.loading = false

	m.updateTableRows()
	m.table.GotoTop()

	// Continue expanding if there's a pending path
	if m.pendingSelectPath != "" {
		return m.expandToPath(m.pendingSelectPath)
	}

	return m, nil
}

// handleLoadError handles LoadErrorMsg
func (m Model) handleLoadError(msg LoadErrorMsg) (tea.Model, tea.Cmd) {
	m.loading = false
	m.firstLoadDone = true
	m.error = msg.Error.Error()
	if msg.ParentNode != nil {
		msg.ParentNode.Loading = false
	}
	return m, nil
}

// expandToPath navigates to and selects a node at the given path after refresh
func (m Model) expandToPath(targetPath string) (tea.Model, tea.Cmd) {
	// Check if the target is on screen. The rows, not currentItems(): under a
	// filter or a non-default sort those are two different orderings, and the
	// cursor indexes the one being shown.
	for i, row := range m.table.Visible() {
		if row.node.FullPath == targetPath {
			m.table.SetCursor(i)
			m.pendingSelectPath = ""
			return m, nil
		}
	}

	// Find an ancestor that needs to be drilled into
	for _, node := range m.currentItems() {
		if node.Type == NodeTypeGroup && strings.HasPrefix(targetPath, node.FullPath+"/") {
			// Drill into this group
			m.navigationStack = append(m.navigationStack, m.currentGroupNode)
			m.currentGroupNode = node

			if node.Children == nil {
				node.Loading = true
				m.updateTableRows()
				return m, m.loadChildren(node)
			}
			node.Expanded = true
			m.updateTableRows()
			return m.expandToPath(targetPath)
		}
	}

	// Could not find path - clear pending and stay where we are
	m.pendingSelectPath = ""
	return m, nil
}

package explorer

import (
	"strings"
	"time"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// Column minimum widths. The table used to size every column as a ratio of the
// available space, which reads as deliberate but is not: at 80 columns Type got
// 5 and Created got 8, neither wide enough for its own header. Floors plus a
// flexible Name and Slug say what actually matters when space is short.
//
// colVisibilityMin is the width of the word "Visibility" and nothing more. The
// cell below it is one glyph, so the header is all the column costs — and there
// is no sort arrow to make room for any more, because the column no longer
// sorts (see below).
const (
	colNameMin       = 20
	colSlugMin       = 16
	colVisibilityMin = 10
	colRoleMin       = 12
	colCreatedMin    = 12
	colActivityMin   = 12
	colCIMin         = 6
)

// Column indices the view and its tests name rather than count. Only the two
// that are referred to by position are declared: the rest are read by title,
// which is what stops a reorder from silently moving an assertion.
const (
	columnName    = 1
	columnCreated = 6
)

// explorerColumns describes the explorer table, in the order it renders:
// icon, Name, Slug, Visibility, Role, CI, Created, Activity.
//
// **CI sits beside Role rather than at the end**, which is where a reader looks
// for what the forge says about a repository — the same argument that put the
// workspaces CI grade beside the severity counters instead of past Modified.
//
// Only Name, Created and Activity sort. A slug orders the same as the name
// beside it; a role has no order anyone would recognise; and neither has a
// visibility — is public before private, or after? Three values in an order
// nobody would agree on are not a sort, and dropping the comparator is what
// lets the header be the whole width of the column: askFor reserves two cells
// for an arrow on every sortable column, sorted or not.
//
// It takes no vocabulary any more. The forge's own words — Group/Project or
// Organization/Repository — left the table with the Type column, and the glyph
// that replaced it belongs to no forge. They are not lost: nodeTypeLabel still
// resolves them for the help legend, which is where a sentence has room to be
// right about a personal account.
//
// The clone selection's checkbox rides on the **icon** cell (row.go:iconCell):
// a column of its own would cost four cells on every screen to say nothing on
// all but one of them, and at 80 columns the explorer has none to spare. What
// makes the sharing honest is the colour — iconStyle paints the node's kind
// whether the glyph is a checkbox or not.
func explorerColumns() []datatable.Column[explorerRow] {
	return []datatable.Column[explorerRow]{
		{
			// No title: the column carries a glyph, and a header over it would
			// name something read at a glance anyway. It declares neither Less
			// nor Search — it adds no text anyone could type, so the filter
			// stays on Name and Slug (Rule 125).
			Title: "", Sizing: datatable.SizingFixed, MinWidth: datatable.IconColumnWidth,
			Cell:  iconCell,
			Style: iconStyle,
		},
		{
			Title: "Name", Sizing: datatable.SizingContent, MinWidth: colNameMin, Flex: 2,
			Cell:   func(r explorerRow) string { return r.node.Name },
			Less:   func(a, b explorerRow) bool { return strings.ToLower(a.node.Name) < strings.ToLower(b.node.Name) },
			Search: func(r explorerRow) string { return r.node.Name },
		},
		{
			Title: "Slug", Sizing: datatable.SizingContent, Optional: true, MinWidth: colSlugMin, Flex: 1,
			Cell: func(r explorerRow) string { return nodeSlug(r.node.FullPath) },
			// The whole path, not the slug shown: a query naming a parent group
			// has always matched, and the slug is a suffix of it anyway.
			Search: func(r explorerRow) string { return r.node.FullPath },
		},
		{
			// A glyph under the whole word. The word is what makes the three
			// glyphs decodable without a legend, and it costs nothing extra:
			// the header is the column's width either way.
			Title: "Visibility", Sizing: datatable.SizingFixed, Optional: true, MinWidth: colVisibilityMin,
			Cell:  func(r explorerRow) string { return visibilityIcon(r.node) },
			Style: func(r explorerRow) lipgloss.Style { return theme.IconStyle(visibilityRole(r.node)) },
		},
		{
			Title: "Role", Sizing: datatable.SizingFixed, Optional: true, MinWidth: colRoleMin,
			Cell: func(r explorerRow) string { return r.node.Role },
		},
		{
			Title: "CI", Sizing: datatable.SizingFixed, Optional: true, MinWidth: colCIMin,
			Cell:  func(r explorerRow) string { return pipelineStatusLabel(r.node) },
			Style: func(r explorerRow) lipgloss.Style { return pipelineStatusStyle(r.node) },
		},
		{
			Title: "Created", Sizing: datatable.SizingFixed, Optional: true, MinWidth: colCreatedMin,
			Cell: func(r explorerRow) string { return timeAgo(r.node.CreatedAt) },
			Less: func(a, b explorerRow) bool { return timeBefore(a.node.CreatedAt, b.node.CreatedAt) },
		},
		{
			Title: "Activity", Sizing: datatable.SizingFixed, Optional: true, MinWidth: colActivityMin,
			Cell: func(r explorerRow) string { return timeAgo(r.node.LastActivityAt) },
			Less: func(a, b explorerRow) bool { return timeBefore(a.node.LastActivityAt, b.node.LastActivityAt) },
		},
	}
}

// timeBefore compares two nullable times (nil is considered "oldest")
func timeBefore(a, b *time.Time) bool {
	if a == nil && b == nil {
		return false
	}
	if a == nil {
		return true
	}
	if b == nil {
		return false
	}
	return a.Before(*b)
}

package explorer

import (
	"log"
	"os/exec"
	"runtime"

	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/keymap"
)

// Update gère les messages
func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.resize(msg.Width, msg.Height)

	case tea.KeyMsg:
		return m.handleKeyMsg(msg)

	case spinner.TickMsg:
		return m.handleSpinnerTick(msg)

	case RootGroupsLoadedMsg:
		m.loading = false
		m.firstLoadDone = true
		m.nodes = msg.Nodes
		m.error = ""
		m.updateTableRows()
		m.table.GotoTop()
		// If there's a pending selection, expand path to it
		if m.pendingSelectPath != "" {
			return m.expandToPath(m.pendingSelectPath)
		}

	case ChildrenLoadedMsg:
		return m.handleChildrenLoaded(msg)

	case LoadErrorMsg:
		return m.handleLoadError(msg)

	case CloneDestinationSelectedMsg:
		return m.handleCloneDestinationSelected(msg)

	case CloneSelectionCancelledMsg:
		// The destination was refused, not the selection: stay in ModeSelecting
		// so the ticks the user made are still there.
		return m, nil

	case CloneEventMsg:
		return m.handleCloneEvent(msg)

	case CloneRunFinishedMsg:
		return m.handleCloneRunFinished()

	case jobs.ChangedMsg:
		return m.handleJobsChanged(msg)

	case components.CreationFormSubmitMsg:
		return m.handleCreationSubmit(msg)

	case components.CreationFormCancelMsg:
		m.mode = ModeNormal
		m.creationForm = nil
		return m, nil

	case TemplatesLoadedMsg:
		return m.handleTemplatesLoaded(msg)

	case GroupCreatedMsg:
		return m.handleGroupCreated(msg)

	case ProjectCreatedMsg:
		return m.handleProjectCreated(msg)

	case components.OptionConfirmModalYesMsg:
		return m.handleDeleteConfirmed(msg.Option)

	case components.OptionConfirmModalNoMsg:
		m.mode = ModeNormal
		m.deleteConfirmModal = nil
		m.deleteTargetNode = nil
		return m, nil

	case DeleteCompleteMsg:
		return m.handleDeleteComplete(msg)

	case BrowserOpenedMsg:
		if msg.Error != nil {
			log.Printf("ERROR [explorer] open browser: %v", msg.Error)
			return m, m.footer.Error("Failed to open browser — check logs")
		}
		return m, nil
	}

	m.footer.Handle(msg)
	return m, nil
}

// View is implemented in view.go

// handleKeyMsg handles keyboard input
func (m Model) handleKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	// Filter bar search mode - prioritaire
	if m.table.InEditMode() {
		return m, m.table.Update(msg)
	}

	// Handle mode-specific input
	switch m.mode {
	case ModeCloning:
		return m.handleCloningKey(msg)
	case ModeSelecting:
		return m.handleSelectingKey(msg)
	case ModeLoadingTemplates:
		// Ignore input while loading templates
		return m, nil
	case ModeCreatingProject:
		if m.creationForm != nil {
			var cmd tea.Cmd
			m.creationForm, cmd = m.creationForm.Update(msg)
			return m, cmd
		}
	case ModeConfirmingDelete:
		if m.deleteConfirmModal != nil {
			var cmd tea.Cmd
			m.deleteConfirmModal, cmd = m.deleteConfirmModal.Update(msg)
			return m, cmd
		}
	}

	// Normal mode. Actions resolve the cursor through the table, which resolves
	// it against the very slice its rows were built from.
	switch msg.String() {
	case "left":
		return m.handleDrillUp()
	case "right":
		return m.handleDrillDown()
	case "esc":
		return m.handleDrillUp()
	case "ctrl+r":
		return m.handleRefresh()
	case keymap.Clone:
		return m.handleCloneStart()
	case keymap.New:
		return m.handleCreateResource()
	case keymap.Delete:
		return m.handleDeleteStart()
	case keymap.Web:
		return m.handleOpenInBrowser()
	}

	// Navigation, `/` and `.` are the table's, not the view's.
	return m, m.table.Update(msg)
}

// handleSelectingKey is the clone selection mode (Rule 135 unchanged): `space`
// ticks, `←→` still drill, `enter` confirms.
//
// `esc` leaves the mode rather than drilling up, because cancelling is what the
// key means when there is something to cancel; `←` is still the way up.
func (m Model) handleSelectingKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case " ":
		return m.handleSelectionToggle()
	case "enter":
		return m.handleSelectionConfirm()
	case "esc":
		return m.handleSelectionCancel()
	case "left":
		return m.handleDrillUp()
	case "right":
		return m.handleDrillDown()
	}
	return m, m.table.Update(msg)
}

// handleCloningKey is the clone list: `esc` cancels, then closes. Navigation,
// `/` and `.` are the list's own table.
func (m Model) handleCloningKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	if m.clone == nil {
		m.mode = ModeNormal
		return m, nil
	}
	// The list has its own filter bar, and its `esc` closes the search. Testing
	// the key first would cancel the run from inside the search box.
	if m.clone.table.InEditMode() {
		return m, m.clone.table.Update(msg)
	}
	if msg.String() == "esc" {
		return m.handleCloneEsc()
	}
	return m, m.clone.table.Update(msg)
}

// handleSpinnerTick advances the spinner the view owns, which is now the
// **load** and nothing else.
//
// It used to drive the clone rows as well, and that was the fourth hand-stamped
// chain D5 removed: the rows take the router's frame from the broadcast now, so
// a clone keeps turning whether or not this view is on screen — and cannot
// freeze on frame zero if this chain dies.
func (m Model) handleSpinnerTick(msg spinner.TickMsg) (tea.Model, tea.Cmd) {
	if !m.loading {
		return m, nil
	}
	var cmd tea.Cmd
	m.spinner, cmd = m.spinner.Update(msg)
	// The load is reported in the footer, so the frame has to reach it — a
	// spinner stuck on frame zero reads as a hang.
	m.footer.SetSpinnerFrame(m.spinner.View())
	return m, cmd
}

// handleOpenInBrowser opens the selected node's web URL in the default browser
func (m Model) handleOpenInBrowser() (tea.Model, tea.Cmd) {
	if browse := m.browsable(); !browse.Enabled() {
		return m, m.footer.Warn(browse.Reason)
	}
	node, _ := m.selectedNode()
	url := node.WebURL
	return m, func() tea.Msg {
		var cmd *exec.Cmd
		switch runtime.GOOS {
		case "darwin":
			cmd = exec.Command("open", url)
		case "windows":
			cmd = exec.Command("cmd", "/c", "start", url)
		default:
			cmd = exec.Command("xdg-open", url)
		}
		return BrowserOpenedMsg{Error: cmd.Start()}
	}
}

package explorer

import (
	"github.com/anthnel/devdesk/internal/forge"
	"github.com/anthnel/devdesk/internal/oci"
)

// DeleteCompleteMsg is sent when a delete operation completes
type DeleteCompleteMsg struct {
	Error       error
	DeletedNode *TreeNode
}

// RootGroupsLoadedMsg est envoyé quand les groupes racine sont chargés
type RootGroupsLoadedMsg struct {
	Nodes []*TreeNode
}

// GroupCreatedMsg est envoyé quand un groupe est créé
type GroupCreatedMsg struct {
	Namespace forge.Namespace
	Error     error
}

// ProjectCreatedMsg est envoyé quand un projet est créé
type ProjectCreatedMsg struct {
	Repository    forge.Repository
	Error         error
	TemplateError error // Non-nil if template application failed (project still exists)
}

// TemplatesLoadedMsg est envoyé quand les templates OCI sont chargées
type TemplatesLoadedMsg struct {
	Templates []oci.TemplateEntry
	Error     error
}

// ChildrenLoadedMsg est envoyé quand les enfants d'un nœud sont chargés
type ChildrenLoadedMsg struct {
	ParentNode *TreeNode
	Children   []*TreeNode
}

// LoadErrorMsg est envoyé en cas d'erreur de chargement
type LoadErrorMsg struct {
	Error      error
	ParentNode *TreeNode // Optional: node that was loading when error occurred
}

// CloneSelectionRequestMsg asks the app to borrow the workspaces view so the
// user can pick where the clones go (decision 5).
type CloneSelectionRequestMsg struct{}

// CloneDestinationSelectedMsg is the app's answer: the chosen directory.
type CloneDestinationSelectedMsg struct {
	Path string
}

// CloneSelectionCancelledMsg is sent by the app when the user backed out of the
// destination picker. The selection is kept — only the destination was refused.
type CloneSelectionCancelledMsg struct{}

// CloneEventMsg carries one pipeline event into Update. The event itself is
// unexported: it is the pipeline's vocabulary, and nothing outside this package
// has anything to do with it.
type CloneEventMsg struct {
	event cloneEvent
}

// CloneRunFinishedMsg is the closed event channel — every clone has returned,
// whether the run was cancelled or ran to the end.
type CloneRunFinishedMsg struct{}

// BrowserOpenedMsg is sent when the browser launch command has been started
type BrowserOpenedMsg struct {
	Error error
}

