13	// is the conversion from the forge's vocabulary to the tree the view renders,
14	// and the two Cmds that carry it into Update.
15	
16	// nodeFromNamespace converts a namespace, keeping the view state on the node.
17	func nodeFromNamespace(ns forge.Namespace, parent *TreeNode) *TreeNode {
18		return &TreeNode{
19			ID:         ns.ID,
20			Name:       ns.Name,
21			FullPath:   ns.Path,
22			Type:       NodeTypeGroup,
23			Parent:     parent,
24			Expanded:   false,
25			Visibility: ns.Visibility,
26			Role:       ns.Role,
27			CreatedAt:  ns.CreatedAt,
28			WebURL:     ns.WebURL,
29		}
30	}
31	
32	// nodeFromRepository converts a repository.
33	func nodeFromRepository(repo forge.Repository, parent *TreeNode) *TreeNode {
34		return &TreeNode{
35			ID:                repo.ID,
36			Name:              repo.Name,
37			FullPath:          repo.Path,
38			Type:              NodeTypeProject,
39			Parent:            parent,
40			Expanded:          false,
41			Visibility:        repo.Visibility,
42			Role:              repo.Role,
43			CreatedAt:         repo.CreatedAt,
44			LastActivityAt:    repo.LastActivityAt,
45			PipelineStatus:    repo.CIStatus,
46			MarkedForDeletion: repo.DeletionScheduled,
47			WebURL:            repo.WebURL,
48		}
49	}
50	
51	// discoverChildren walks a namespace for the recursive clone: the nodes it
52	// returns carry a type and a path, which is all a clone reads.
53	//
54	// It asks for no decoration, which is what keeps a clone from paying two extra
55	// requests per repository for a CI badge and a role it never looks at. The
56	// nodes are therefore **not** interchangeable with the ones the explorer
57	// browses, and must not be stored on the tree the view renders: the role and CI
58	// columns would go blank for every group a clone had walked through.
59	func discoverChildren(ctx context.Context, backend forge.Forge, parent *TreeNode, includeArchived bool) ([]*TreeNode, error) {
60		children, err := backend.Children(ctx, parent.ID, forge.BrowseOptions{IncludeArchived: includeArchived})
61		if err != nil {
62			return nil, err
63		}
64	
65		nodes := make([]*TreeNode, 0, len(children.Namespaces)+len(children.Repositories))
66		for _, ns := range children.Namespaces {
67			nodes = append(nodes, nodeFromNamespace(ns, parent))
68		}
69		for _, repo := range children.Repositories {
70			nodes = append(nodes, nodeFromRepository(repo, parent))
71		}
72		return nodes, nil
73	}
74	
75	// loadRootGroups charge les groupes racine, décorés.
76	func (m Model) loadRootGroups() tea.Cmd {
77		backend := m.shared.Forge
78	
79		return func() tea.Msg {
80			namespaces, err := backend.RootNamespaces(context.Background(), forge.BrowseOptions{Decorated: true})
81			if err != nil {
82				return LoadErrorMsg{Error: err}
83			}
84	
85			nodes := make([]*TreeNode, len(namespaces))
86			for i, ns := range namespaces {
87				nodes[i] = nodeFromNamespace(ns, nil)
88			}
89			return RootGroupsLoadedMsg{Nodes: nodes}
90		}
91	}
92	
93	// loadChildren charge les sous-groupes et projets d'un groupe, décorés : la vue
94	// affiche le rôle et le statut CI en colonnes.
95	//
96	// Elle liste les dépôts archivés — l'explorer montre ce qui est là.
97	// `forge.pull.include_archived` ne concerne que le clone, et c'est
98	// discoverChildren qui le lit.
99	func (m Model) loadChildren(parentNode *TreeNode) tea.Cmd {
100		backend := m.shared.Forge
101	
102		return func() tea.Msg {
103			children, err := backend.Children(context.Background(), parentNode.ID, forge.BrowseOptions{
104				IncludeArchived: true,
105				Decorated:       true,
106			})
107			if err != nil {
108				return LoadErrorMsg{Error: err, ParentNode: parentNode}
109			}
110	
111			nodes := make([]*TreeNode, 0, len(children.Namespaces)+len(children.Repositories))
112			for _, ns := range children.Namespaces {
113				nodes = append(nodes, nodeFromNamespace(ns, parentNode))
114			}
115			for _, repo := range children.Repositories {
116				nodes = append(nodes, nodeFromRepository(repo, parentNode))
117			}
118	
119			return ChildrenLoadedMsg{ParentNode: parentNode, Children: nodes}
120		}
121	}
