481	func TestTemplateFailureStillOpensTheForm(t *testing.T) {
482		m := feed(t, loadedModel(t), testutil.Key(keymap.New))
483	
484		m = feed(t, m, TemplatesLoadedMsg{Error: errors.New("registry unreachable")})
485	
486		if m.creationForm == nil {
487			t.Fatal("a registry error suppressed the creation form")
488		}
489		if len(m.templateEntries) != 0 {
490			t.Errorf("templateEntries = %v after a registry error, want none", m.templateEntries)
491		}
492	
493		m = feed(t, m, testutil.Key("right")) // Group -> Project
494		if view := m.creationForm.View(); !strings.Contains(view, "Registry error") {
495			t.Errorf("the unfocused Template field does not mention the registry failure:\n%s", view)
496		}
497	
498		m = feed(t, m, testutil.Keys("down", "down", "down", "down")...) // onto Template
499		if view := m.creationForm.View(); !strings.Contains(view, "Registry error") {
500			t.Errorf("the focused Template field does not mention the registry failure:\n%s", view)
501		}
502	}
