504	func TestCancellingCreationReturnsToNormal(t *testing.T) {
505		m := feed(t, loadedModel(t), testutil.Key(keymap.New), TemplatesLoadedMsg{})
506	
507		m = feed(t, m, components.CreationFormCancelMsg{})
508	
509		if m.mode != ModeNormal || m.creationForm != nil {
510			t.Errorf("mode = %v, form = %v after cancelling", m.mode, m.creationForm)
511		}
512	}
