514	// A created resource is selected after the refresh, so the user sees what they
515	// just made instead of having to hunt for it.
516	func TestCreationSchedulesASelection(t *testing.T) {
517		m := feed(t, loadedModel(t), GroupCreatedMsg{Namespace: newGroup(7, "alpha/new")})
518	
519		if m.pendingSelectPath != "alpha/new" {
520			t.Errorf("pendingSelectPath = %q after creating a group", m.pendingSelectPath)
521		}
522		if !m.loading {
523			t.Error("creating a group did not trigger a refresh")
524		}
525	}
