527	func TestCreationFailureIsReported(t *testing.T) {
528		m := feed(t, loadedModel(t), GroupCreatedMsg{Error: errors.New("name has already been taken")})
529	
530		if !strings.Contains(m.error, "already been taken") {
531			t.Errorf("error = %q, want the API message", m.error)
532		}
533		if m.loading {
534			t.Error("a failed creation triggered a refresh")
535		}
536	}
