538	// A project whose template failed still exists, so the refresh must happen and
539	// the message has to say both things.
540	func TestProjectCreatedWithAFailedTemplateStillRefreshes(t *testing.T) {
541		m := feed(t, loadedModel(t), ProjectCreatedMsg{
542			Repository:    newProject(9, "alpha/svc"),
543			TemplateError: errors.New("download template: 404"),
544		})
545	
546		if !m.loading {
547			t.Error("a template failure suppressed the refresh of a project that was created")
548		}
549		if !strings.Contains(m.error, "template failed") {
550			t.Errorf("error = %q, want it to say the project exists but the template did not apply", m.error)
551		}
552		if m.pendingSelectPath != "alpha/svc" {
553			t.Errorf("pendingSelectPath = %q, want the created project", m.pendingSelectPath)
554		}
555	}
