557	// The form decides which API call the submit becomes; the view routes on
558	// FormType alone.
559	func TestCreationSubmitRoutesOnTheFormType(t *testing.T) {
560		for _, formType := range []components.FormType{components.FormTypeGroup, components.FormTypeProject} {
561			m, cmd := step(t, loadedModel(t), components.CreationFormSubmitMsg{
562				FormType: formType, Name: "new thing", Visibility: "private",
563			})
564	
565			if cmd == nil {
566				t.Errorf("submitting form type %v issued no command", formType)
567			}
568			if m.mode != ModeNormal || m.creationForm != nil {
569				t.Errorf("submitting left mode=%v form=%v", m.mode, m.creationForm)
570			}
571		}
572	}
