574	// Submitting after the session expired must say so rather than panic on a nil
575	// client inside the command.
576	func TestCreationSubmitWithoutAClientReports(t *testing.T) {
577		m := feed(t, New(testConfig(), &shared.State{}), tea.WindowSizeMsg{Width: 160, Height: 30})
578	
579		m, cmd := step(t, m, components.CreationFormSubmitMsg{FormType: components.FormTypeGroup, Name: "x"})
580	
581		if cmd != nil {
582			t.Errorf("submitting with no forge issued %T", testutil.Msg(cmd))
583		}
